css:
.loader { position: relative; overflow: hidden; display: flex; flex-direction: column; justify-content: flex-end; gap: calc(var(--loader-size) * .05); width: var(--loader-size); height: calc(var(--loader-size) * .6); padding: calc(var(--loader-size) * .07); border-radius: calc(var(--loader-size) * .08); background: color-mix(in srgb, var(--loader-color) 14%, transparent); box-sizing: border-box; }
.loader .row { height: calc(var(--loader-size) * .06); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 32%, transparent); }
.loader .row:last-child { width: 55%; }
.loader .glow { position: absolute; top: 0; bottom: 0; left: 0; right: 0; background: linear-gradient(115deg, transparent 30%, color-mix(in srgb, var(--loader-color) 45%, transparent) 50%, transparent 70%); animation: twSweep calc(var(--loader-speed) * 1.6) linear infinite; }
@keyframes twSweep { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }
